    timedCues: [{"startMs": 0, "endMs": 30000, "textEn": "Glad Tidings and the Prophetic Line", "textAr": ""}, {"startMs": 30000, "endMs": 60000, "textEn": "Glad tidings of Ishaq came to Ibrahim and Sarah in old age. Commentators related that Ibrahim sought for him a righteous wife from his kin rather than from pagan Canaanites.", "textAr": ""}, {"startMs": 60000, "endMs": 90000, "textEn": "From Ishaq came Yaqub (Israel), continuing the prophetic line among the Children of Israel. Though the Quran gives few personal episodes of Ishaq’s life, he is named among the guided prophets.", "textAr": ""}, {"startMs": 90000, "endMs": 120000, "textEn": "Ibn Kathir places him as a link of blessing between Ibrahim and the tribes that would later receive Musa, Dawud, and many messengers.", "textAr": ""}],
