    hasAudio: false,
    audioUrl: "https://cdn.storiesofislam.example/audio/qisas/sulaiman-and-the-dominion.mp3",
    timedCues: [{"startMs": 0, "endMs": 24000, "textEn": "A Kingdom Unlike Any Other", "textAr": ""}, {"startMs": 24000, "endMs": 48000, "textEn": "Sulaiman inherited Dawud’s prophethood and a kingdom unlike any other. Allah taught him the speech of birds, subjected the wind and the jinn to his command, and poured molten copper for his works.", "textAr": ""}, {"startMs": 48000, "endMs": 72000, "textEn": "The Queen of Saba", "textAr": ""}, {"startMs": 72000, "endMs": 96000, "textEn": "He reviewed the hoopoe, which brought news of Bilqis and her people’s sun-worship. Sulaiman sent a letter calling her to Allah.", "textAr": ""}, {"startMs": 96000, "endMs": 120000, "textEn": "Her throne was brought in an instant; she recognized the sign, abandoned sun-worship, and submitted with Sulaiman to the Lord of the worlds. Power used to invite, not to tyrannize.", "textAr": ""}],
